import"chrome://resources/cr_elements/cr_toggle/cr_toggle.js";import{assert}from"chrome://resources/js/assert.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{EnterpriseReportingBrowserProxy}from"./browser_proxy.js";import{getTemplate}from"./reporting_history.html.js";export class ReportingHistoryElement extends PolymerElement{constructor(){super(...arguments);this.browserProxy=EnterpriseReportingBrowserProxy.getInstance()}static get is(){return"reporting-history-element"}static get template(){return getTemplate()}static get properties(){return{loggingState:Boolean}}loggingStateToString(checked){return checked?"on":"off"}onToggleChange(event){event.stopPropagation();this.browserProxy.handler.recordDebugState(event.detail)}connectedCallback(){super.connectedCallback();this.setEmptyErpTable();this.browserProxy.callbackRouter.setErpHistoryData.addListener((history=>{this.updateErpTable(history)}))}ready(){super.ready();this.browserProxy.handler.getDebugState().then((({state:state})=>{this.loggingState=state}));this.browserProxy.handler.getErpHistoryData().then((({historyData:historyData})=>{this.updateErpTable(historyData)}))}setEmptyErpTable(){const emptyRow=document.createElement("tr");emptyRow.replaceChildren(this.createHistoryTableDataCell("No events","erp-type"),this.composeEventParameters([],"erp-parameters"),this.createHistoryTableDataCell("","erp-status"),this.createHistoryTableDataCell("","erp-timestamp"));this.$.body.appendChild(emptyRow)}updateErpTable(history){this.$.body.replaceChildren();if(history.events.length===0){this.setEmptyErpTable();return}for(const event of history.events.reverse()){const row=this.composeTableRow(event);this.$.body.appendChild(row)}}composeTableRow(event){const row=document.createElement("tr");row.replaceChildren(this.createHistoryTableDataCell(this.erpHistoryTypeToString(event.call),"erp-type"),this.composeEventParameters(event.parameters,"erp-parameters"),this.createHistoryTableDataCell(event.status,"erp-status"),this.createHistoryTableDataCell(this.timestampToString(Number(event.time)),"erp-timestamp"));return row}composeEventParameters(parameters,className){const list=document.createElement("ul");for(const parameter of parameters){const line=document.createElement("li");line.textContent=parameter.name+": "+parameter.value;list.appendChild(line)}const element=document.createElement("td");element.appendChild(list);element.classList.add(className);return element}createHistoryTableDataCell(textContent,className){const td=document.createElement("td");td.classList.add(className);td.textContent=textContent;return td}erpHistoryTypeToString(erpHistoryType){return erpHistoryType||"Unknown"}timestampToString(timestampSeconds){if(timestampSeconds===0){return"N/A"}assert(!Number.isNaN(timestampSeconds));const timestamp=new Date(timestampSeconds*1e3);const now=new Date;if(timestamp.getDate()===now.getDate()){return timestamp.toLocaleTimeString()}return timestamp.toLocaleString()}}customElements.define(ReportingHistoryElement.is,ReportingHistoryElement);